"""Exhaustive cheat-set enumeration for the n-fold parallel repetition.

Computes, by brute force over all q^n challenge vectors, the set of challenge
vectors an already-committed prover can answer, and certifies the rigidity
bound: without a witness the cheat set has at most one element.
"""

from __future__ import annotations

from itertools import product
from typing import List, Sequence, Set, Tuple


def answerable(k: int, target: int, q: int, a: int, c: int) -> bool:
    """Is there any z in F_q with k*z = a + c*target?  (Unbounded prover.)"""
    return any((k * z) % q == (a + c * target) % q for z in range(q))


def cheat_set(
    k: int, target: int, q: int, commitments: Sequence[int]
) -> Set[Tuple[int, ...]]:
    """All challenge vectors the optimal unbounded prover can answer.

    Because the verification equation decouples across rounds once the
    commitments are fixed, the optimum is round-wise: a vector is answerable
    iff every coordinate is.  Cost: O(q^n * n * q) checks, or O(n*q^2) if the
    per-round answerability table is precomputed as below.
    """
    n = len(commitments)
    table: List[List[bool]] = [
        [answerable(k, target, q, commitments[i], c) for c in range(q)]
        for i in range(n)
    ]
    return {
        tuple(c)
        for c in product(range(q), repeat=n)
        if all(table[i][c[i]] for i in range(n))
    }


def max_cheat_set_size(k: int, target: int, q: int, n: int) -> int:
    """Worst case over every possible commitment vector.

    Cost: O(q^n) commitment vectors times the cost above; feasible only for
    tiny parameters, which suffices to certify the bound empirically.
    """
    return max(
        len(cheat_set(k, target, q, commitments))
        for commitments in product(range(q), repeat=n)
    )


def soundness_fraction(k: int, target: int, q: int, n: int) -> float:
    """Worst-case accepting fraction; the theory bounds this by q^{-n}
    whenever the statement has no witness."""
    return max_cheat_set_size(k, target, q, n) / (q ** n)


def demo() -> None:
    # False statement over F_5: the zero map cannot hit the target 1.
    k, target, q = 0, 1, 5
    for n in (1, 2, 3):
        frac = soundness_fraction(k, target, q, n)
        print(f"n = {n}: worst-case fraction = {frac:.6f}, "
              f"bound q^-n = {q ** -n:.6f}")

    # True statement over F_5: the identity map with target 3.
    k, target = 1, 3
    for n in (1, 2):
        commitments = tuple(0 for _ in range(n))
        print(f"true statement, n = {n}: |cheat set| = "
              f"{len(cheat_set(k, target, q, commitments))} of {q ** n}")


if __name__ == "__main__":
    demo()

"""Forgery-free hash construction by image colouring, and the search for
non-interactive forgeries.

A non-interactive (hash-generated challenge) proof for the statement
"exists w with f(w) = T" is a pair (a, z) accepted when the challenge equals
Hash(a).  A hash is forgery-free when no such pair exists.  The theory says a
forgery-free hash exists precisely when the statement is FALSE, and exhibits
one explicitly: colour the image of f with 1 and everything else with 0.
"""

from __future__ import annotations

from typing import Callable, List, Optional, Tuple


def hom(k: int, m: int, x: int) -> int:
    return (k * x) % m


def chi(c: int, x: int, m: int) -> int:
    """Boolean challenge selector: chi(0, x) = 0, chi(1, x) = x."""
    return x % m if c == 1 else 0


def find_forgery(
    k: int, target: int, m: int, hash_fn: Callable[[int], int]
) -> Optional[Tuple[int, int]]:
    """Search for an accepted non-interactive pair (a, z).

    By the fixed-point description, such a pair exists iff for some response z
    and some challenge bit c one has Hash(f(z) - chi(c, T)) = c.  Scanning all
    z and both bits costs O(|G|) hash evaluations.
    """
    for z in range(m):
        for c in (0, 1):
            a = (hom(k, m, z) - chi(c, target, m)) % m
            if hash_fn(a) == c:
                return (a, z)
    return None


def image_of(k: int, m: int) -> List[int]:
    return sorted({hom(k, m, x) for x in range(m)})


def image_hash(k: int, m: int) -> Callable[[int], int]:
    """The canonical candidate: 1 on the image of f, 0 elsewhere.

    Cost: O(|G|) to tabulate the image, O(1) per evaluation.
    """
    image = set(image_of(k, m))
    return lambda a: 1 if a % m in image else 0


def build_forgery_free_hash(
    k: int, target: int, m: int
) -> Optional[Callable[[int], int]]:
    """Return a forgery-free hash if one exists, else None.

    The statement has a witness iff target lies in the image of f; in that case
    NO hash is forgery-free and None is returned.  Otherwise the image
    colouring works, and is returned.  Cost: O(|G|).
    """
    if target % m in set(image_of(k, m)):
        return None
    return image_hash(k, m)


def demo() -> None:
    m, k = 6, 2
    for target, label in ((4, "true  2w=4"), (1, "false 2w=1")):
        h = build_forgery_free_hash(k, target, m)
        if h is None:
            print(f"{label}: no forgery-free hash exists (statement is true)")
        else:
            forgery = find_forgery(k, target, m, h)
            print(f"{label}: image colouring is forgery-free = {forgery is None}")


if __name__ == "__main__":
    demo()

algorithms.pseudocode:
INPUT : group order m, coefficient k, target T
OUTPUT: certificate record

1. witnesses <- { w : (k*w) mod m == T mod m }
2. kernel    <- { x : (k*x) mod m == 0 }
3. for c in {0,1}:
4.     SimView <- multiset{ ((k*z - chi(c,T)) mod m, c, z) : z in G }
5.     for each w in witnesses:
6.         RealView <- multiset{ ((k*r) mod m, c, (r + chi(c,w)) mod m) : r in G }
7.         record  RealView == SimView                 -- perfect zero knowledge
8.     Acc <- { (a,c,z) : (k*z) mod m == (a + chi(c,T)) mod m }
9.     record  set(Acc) == set(SimView)                -- geometry of acceptance
10.    record  |Acc|                                   -- theory: equals |G|
11. return the record (also containing |witnesses| and |kernel|)

